'use strict';

// MODULES //

var tape = require( 'tape' );
var array = require( '@stdlib/ndarray/array' );
var Float64Array = require( '@stdlib/array/float64' );
var Model = require( './../lib/model.js' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof Model, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function supports modified Huber loss', function test( t ) {
	var expected;
	var model;
	var opts;
	var eta;
	var x;

	eta = 0.1;
	opts = {
		'lambda': 0.0,
		'learningRate': [ 'constant', eta ],
		'loss': 'modifiedHuber',
		'intercept': false
	};
	x = array( new Float64Array( [ 1.0 ] ) );

	// Case 1: `-1 <= y*f(x) < 1` (quadratically smoothed region), where the update is `2*eta*( y - d*y )` (see stdlib-js/stdlib#13111):
	model = new Model( 1, opts );
	model._weights[ 0 ] = 0.3; // eslint-disable-line no-underscore-dangle
	model.update( x, 1 );
	expected = 0.3 + ( 2.0*eta*( 1.0-(0.3*1.0) ) );
	t.strictEqual( model._weights[ 0 ], expected, 'returns expected value' ); // eslint-disable-line no-underscore-dangle

	// Case 2: `y*f(x) >= 1`, where the gradient is zero and the weights are unchanged:
	model = new Model( 1, opts );
	model._weights[ 0 ] = 2.0; // eslint-disable-line no-underscore-dangle
	model.update( x, 1 );
	t.strictEqual( model._weights[ 0 ], 2.0, 'returns expected value' ); // eslint-disable-line no-underscore-dangle

	// Case 3: `y*f(x) < -1`, where the update is `4*eta*y`:
	model = new Model( 1, opts );
	model._weights[ 0 ] = -2.0; // eslint-disable-line no-underscore-dangle
	model.update( x, 1 );
	expected = -2.0 + ( 4.0*eta*1.0 );
	t.strictEqual( model._weights[ 0 ], expected, 'returns expected value' ); // eslint-disable-line no-underscore-dangle

	t.end();
});
